// Why `report` was rejected.
// unknown_delivery: No delivery with this id belongs to the reporting worker API key, or
// that key is revoked.
// wrong_secret: The secret does not match the one issued in `accepted`, or the delivery was
// never accepted, so no secret was issued.
// not_in_flight: The secret matched, but the delivery already has its one final report.
type ReportRejection string

const (
	NotInFlight                    ReportRejection = "not_in_flight"
	ReportRejectionUnknownDelivery ReportRejection = "unknown_delivery"
	WrongSecret                    ReportRejection = "wrong_secret"
)

type ReportRejectedEventType string

const (
	TypeReportRejected ReportRejectedEventType = "report_rejected"
)

